SELECT COALESCE(MAX(seq), 0)
FROM chat_message
WHERE tenant_id = #{tenantId}
  AND user_id = #{userId}
  AND session_id = #{sessionId}

SELECT seq, role, content, run_id, created_at
FROM chat_message
WHERE tenant_id = #{tenantId}
  AND user_id = #{userId}
  AND session_id = #{sessionId}
ORDER BY seq ASC
LIMIT #{limit}
